WITH with_dims AS (SELECT e.id, e.order_id, e.product_id, e.quantity, o.amount, o.status, o.discount FROM order_items e LEFT JOIN orders o ON e.order_id = o.id), joined AS (SELECT a.id, a.product_id, a.status, p.launch_date, p.product_name, p.stock_qty FROM with_dims a LEFT JOIN products p ON a.product_id = p.id WHERE ARRAY_CONTAINS(p.tags, 'sale')), valid AS (SELECT *, CASE WHEN stock_qty >= 431 THEN 'High' WHEN stock_qty >= 142 THEN 'Medium' ELSE 'Low' END stock_qty_band, COALESCE(status, 'DIRECT') resolved_status FROM joined WHERE launch_date <= '2023-12-01'), enriched AS (SELECT id, status, RANK() OVER (PARTITION BY MONTH(launch_date) ORDER BY stock_qty NULLS FIRST) stock_qty_rank, ROW_NUMBER() OVER (PARTITION BY product_id, status ORDER BY stock_qty, id) event_seq, LAG(stock_qty, 2) OVER (ORDER BY stock_qty, id) prev_stock_qty, LEAD(stock_qty, 2) OVER (PARTITION BY status ORDER BY launch_date, id) next_stock_qty FROM valid), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY event_seq DESC NULLS LAST, id) AS rn FROM enriched QUALIFY rn = 1), enriched_order_items AS (SELECT *, NTILE(5) OVER (ORDER BY stock_qty_rank, id) stock_qty_rank_bucket, ROW_NUMBER() OVER w_recent seq_no, NTILE(10) OVER (ORDER BY next_stock_qty, id) next_stock_qty_bucket, FIRST_VALUE(event_seq) IGNORE NULLS OVER (PARTITION BY status ORDER BY stock_qty_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_event_seq FROM deduped WINDOW w_recent AS (PARTITION BY status ORDER BY event_seq DESC, id)) SELECT status, seq_no, ROUND(AVG(first_known_event_seq), 2) AS avg_first_known_event_seq, SORT_ARRAY(COLLECT_SET(status)) AS status_list, SORT_ARRAY(COLLECT_SET(status)) AS status_list_2, COUNT(CASE WHEN status = 'RETURNED' THEN 1 END) AS returned_count, APPROX_PERCENTILE(event_seq, 0.9) AS event_seq_p90, COUNT(*) AS event_count, GROUPING(status) AS grouping_level FROM enriched_order_items GROUP BY ROLLUP (status, seq_no) HAVING avg_first_known_event_seq > 0
